//! Owned compatibility operations shared by Rust and checked translation.
//!
//! These library implementations are intentionally not translated. The
//! translator binds this complete facade and checks its supported operand domain.

mod primitives;
pub use self::primitives::{Json, Maybe, Outcome, Str};
pub use self::primitives::{unicode_scalar_count, ascii_chars_in};
pub use self::primitives::{json_copy, json_with_field};
pub use self::primitives::{json_parse, json_parse_bytes};
pub use self::primitives::{json_index_str, json_index_usize, json_map_index};

mod json_collections;
pub use self::json_collections::{json_map, json_filter_map};

mod ranges;
pub use self::ranges::f64_inclusive_contains;

mod base64;
pub use self::base64::{
    Base64Error, base64_standard_decode_owned_text, base64_standard_decode_text,
    base64_standard_encode_bytes, base64_standard_encode_owned_bytes, base64_standard_encode_text,
    base64_standard_no_pad_decode_text, base64_standard_no_pad_encode_text,
    base64_url_no_pad_decode_owned_text, base64_url_no_pad_decode_text,
    base64_url_no_pad_encode_array32, base64_url_no_pad_encode_bytes,
    base64_url_no_pad_encode_owned_bytes, base64_url_no_pad_encode_owned_text,
};

/// Owned UTF-8 text returned by the compatibility formatting operation.
pub type Text = ::std::string::String;

#[doc(hidden)]
#[macro_export]
macro_rules! __router_translation_core_format {
    ($($arguments:tt)*) => { ::std::format!($($arguments)*) };
}

/// Format through Rust's library; translation checks the primitive format subset.
pub use crate::__router_translation_core_format as format;

#[doc(hidden)]
#[macro_export]
macro_rules! __router_translation_core_json {
    ($($tokens:tt)*) => { ::serde_json::json!($($tokens)*) };
}

/// Construct JSON through the library; translation checks each supported value.
pub use crate::__router_translation_core_json as json;

#[doc(hidden)]
#[macro_export]
macro_rules! __router_translation_core_vec {
    ($($arguments:tt)*) => { ::std::vec!($($arguments)*) };
}

/// Construct a vector through Rust; translation checks the bounded comma-list subset.
pub use crate::__router_translation_core_vec as vec;

#[doc(hidden)]
#[macro_export]
macro_rules! __router_translation_core_matches {
    ($($arguments:tt)*) => { ::std::matches!($($arguments)*) };
}

/// Test scalar literal patterns; translation checks every subject and alternative.
pub use crate::__router_translation_core_matches as matches;

/// Test checked Copy/no-Drop unit-enum constructors; library internals stay native.
pub use crate::__router_translation_core_matches as matches_unit;

//! Primitive types in the owned Rust/JavaScript compatibility interface.

/// A borrowed UTF-8 string slice, with ordinary Rust reference lifetimes.
///
/// The alias allocates no storage and does not transfer ownership. The checked
/// translation binds qualified references to its existing borrowed-text domain;
/// it does not translate the standard library implementation of `str`.
pub type Str = ::std::primitive::str;

/// JSON values use the registered immutable checked representation in translation.
/// The serde_json implementation remains an untranslated native dependency.
pub type Json = ::serde_json::Value;

/// Optional values retain Rust's ordinary variant, borrowing and Drop behavior.
pub type Maybe<T> = ::std::option::Option<T>;

/// Success and failure values retain both payloads and their ownership behavior.
pub type Outcome<T, E> = ::std::result::Result<T, E>;

/// Count Unicode scalar values, not UTF-8 bytes, UTF-16 units or graphemes.
/// The library iterator implementation remains intentionally untranslated.
#[must_use]
pub fn unicode_scalar_count(value: &Str) -> usize {
    value.chars().count()
}

/// Copy one canonical JSON value without sharing mutable storage.
/// Translation uses a bounded immutable deep copy (4096 nodes, depth 32).
#[must_use]
pub fn json_copy(value: &Json) -> Json {
    ::std::clone::Clone::clone(value)
}

/// Set a string key on an owned object (or promote Null to an object).
/// Non-object, non-null bases panic, matching serde_json string indexing.
/// Arguments evaluate once, left to right. Allocation/Drop internals remain
/// untranslated; translation admits bounded successful-resource projections.
#[must_use]
pub fn json_with_field(mut base: Json, key: &Str, value: Json) -> Json {
    base[key] = value;
    base
}

/// Read a string key; absent keys and non-object values return JSON Null.
/// The returned reference borrows only `value`, never the key.
#[must_use]
pub fn json_index_str<'a>(value: &'a Json, key: &Str) -> &'a Json {
    &value[key]
}

/// Read an array position; absent positions and non-arrays return JSON Null.
/// The returned reference borrows only `value`.
#[must_use]
pub fn json_index_usize<'a>(value: &'a Json, index: usize) -> &'a Json {
    &value[index]
}

/// Read an existing map entry, panicking when the key is absent.
/// This differs from Value indexing and never inserts an entry.
#[must_use]
pub fn json_map_index<'a>(
    value: &'a ::serde_json::Map<::std::string::String, Json>,
    key: &Str,
) -> &'a Json {
    &value[key]
}

/// Decode canonical JSON text, discarding only the native parser's error value.
/// Successful JSON null is `Some(Json::Null)`, distinct from invalid JSON.
/// The checked translation uses its bounded, source-selected roundtrip adapter;
/// native serde_json allocation, parser and error Drop internals stay untranslated.
#[must_use]
pub fn json_parse(value: &Str) -> Maybe<Json> {
    ::serde_json::from_str::<Json>(value).ok()
}

/// Decode canonical JSON bytes with the same optional success boundary.
/// Invalid JSON or UTF-8 returns None; translation adapter-domain errors throw.
#[must_use]
pub fn json_parse_bytes(value: &[u8]) -> Maybe<Json> {
    ::serde_json::from_slice::<Json>(value).ok()
}

/// Test every UTF-8 byte against an ASCII alphabet, including vacuous empty input.
/// Non-ASCII alphabet characters never permit a non-ASCII input byte.
/// Both arguments evaluate once, left to right; native iterator internals stay untranslated.
#[must_use]
pub fn ascii_chars_in(value: &Str, alphabet: &Str) -> bool {
    value.bytes().all(|byte| byte.is_ascii() && alphabet.as_bytes().contains(&byte))
}

//! Concrete owned base64 APIs. Native library internals are not translated.

use super::{Outcome, Str, Text};

/// Preserve the native error identity, fields, Display, Debug and conversions.
pub type Base64Error = ::base64::DecodeError;

/// Encode borrowed bytes with the canonical padded standard alphabet.
#[must_use]
pub fn base64_standard_encode_bytes(value: &[u8]) -> Text {
    ::base64::Engine::encode(&::base64::engine::general_purpose::STANDARD, value)
}

/// Encode borrowed scalar text as UTF-8, with canonical standard padding.
#[must_use]
pub fn base64_standard_encode_text(value: &Str) -> Text {
    ::base64::Engine::encode(&::base64::engine::general_purpose::STANDARD, value)
}

/// Consume owned bytes at the same native call boundary as Engine::encode.
#[must_use]
pub fn base64_standard_encode_owned_bytes(value: ::std::vec::Vec<u8>) -> Text {
    ::base64::Engine::encode(&::base64::engine::general_purpose::STANDARD, value)
}

/// Encode borrowed scalar text without standard-alphabet padding.
#[must_use]
pub fn base64_standard_no_pad_encode_text(value: &Str) -> Text {
    ::base64::Engine::encode(&::base64::engine::general_purpose::STANDARD_NO_PAD, value)
}

/// Encode borrowed bytes with the URL alphabet and no padding.
#[must_use]
pub fn base64_url_no_pad_encode_bytes(value: &[u8]) -> Text {
    ::base64::Engine::encode(&::base64::engine::general_purpose::URL_SAFE_NO_PAD, value)
}

/// Consume owned bytes while encoding with the unpadded URL alphabet.
#[must_use]
pub fn base64_url_no_pad_encode_owned_bytes(value: ::std::vec::Vec<u8>) -> Text {
    ::base64::Engine::encode(&::base64::engine::general_purpose::URL_SAFE_NO_PAD, value)
}

/// Consume owned text while encoding its UTF-8 with the unpadded URL alphabet.
#[must_use]
pub fn base64_url_no_pad_encode_owned_text(value: Text) -> Text {
    ::base64::Engine::encode(&::base64::engine::general_purpose::URL_SAFE_NO_PAD, value)
}

/// Keep the concrete by-value 32-byte primitive array contract.
#[must_use]
pub fn base64_url_no_pad_encode_array32(value: [u8; 32]) -> Text {
    ::base64::Engine::encode(&::base64::engine::general_purpose::URL_SAFE_NO_PAD, value)
}

/// Decode borrowed text, preserving every native standard-alphabet error.
pub fn base64_standard_decode_text(value: &Str) -> Outcome<::std::vec::Vec<u8>, Base64Error> {
    ::base64::Engine::decode(&::base64::engine::general_purpose::STANDARD, value)
}

/// Consume owned text, preserving every native standard-alphabet error.
pub fn base64_standard_decode_owned_text(value: Text) -> Outcome<::std::vec::Vec<u8>, Base64Error> {
    ::base64::Engine::decode(&::base64::engine::general_purpose::STANDARD, value)
}

/// Decode borrowed standard text with padding strictly forbidden.
pub fn base64_standard_no_pad_decode_text(value: &Str) -> Outcome<::std::vec::Vec<u8>, Base64Error> {
    ::base64::Engine::decode(&::base64::engine::general_purpose::STANDARD_NO_PAD, value)
}

/// Decode borrowed URL text with padding strictly forbidden.
pub fn base64_url_no_pad_decode_text(value: &Str) -> Outcome<::std::vec::Vec<u8>, Base64Error> {
    ::base64::Engine::decode(&::base64::engine::general_purpose::URL_SAFE_NO_PAD, value)
}

/// Consume owned URL text, preserving native padding and trailing-bit errors.
pub fn base64_url_no_pad_decode_owned_text(value: Text) -> Outcome<::std::vec::Vec<u8>, Base64Error> {
    ::base64::Engine::decode(&::base64::engine::general_purpose::URL_SAFE_NO_PAD, value)
}

